event.ScriptBlockText:
$tomcat_dir = "C:\Program Files\SysAidServer\tomcat\webapps"
function cleanLL { Get-ChildItem "C:\Program Files\SysAidServer\tomcat\logs" | Remove-Item -Force }
while(1) {
  if (Test-Path "$tomcat_dir\usersfiles.war") { Remove-Item -Path "$tomcat_dir\usersfiles.war" -Force; cleanLL }
  sleep 30
}

$tomcat_dir = "C:\Program Files\SysAidServer\tomcat"
Get-ChildItem "$tomcat_dir\logs" -Filter *.log | Where-Object { $_.LastWriteTime -lt (Get-Date).AddDays(-30) } | ForEach-Object { Remove-Item -Path "$tomcat_dir\logs\$($_.Name)" -Force }
sleep 5
